// Package awsshapes holds the compiled-in Smithy shape tables that let
// Overcast speak AWS wire protocols as a *client*: turn a JSON document into a
// real request for any modeled operation of a service Overcast implements, and
// turn that service's response back into a document.
//
// Its consumer is Step Functions' `aws-sdk:<service>:<action>` integration,
// which has to reach every protocol Overcast serves — AWS JSON, Query, EC2
// Query, REST-JSON, REST-XML and Smithy RPC v2 CBOR — through the emulator's
// own router.
//
// The tables are generated by cmd/awsmodelgen from the pinned AWS models (see
// models/aws/sdk-shapes-services.txt) into one `shapes_<service>.gen.go` file
// per service, each a line-per-shape string constant. Nothing is decoded at
// startup: a service's table is parsed the first time Lookup asks for it, and
// cached for the life of the process.
package awsshapes

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
	"sync"

	"github.com/overcast-sh/overcast/internal/awsapi"
)

// Kind is a Smithy shape type.
type Kind uint8

// Shape kinds, named after the Smithy types they stand for. Set is folded into
// List and IntEnum into Integer by the decoder, because nothing on the wire
// tells them apart.
const (
	KindUnknown Kind = iota
	KindStructure
	KindUnion
	KindList
	KindMap
	KindString
	KindEnum
	KindBlob
	KindBoolean
	KindByte
	KindShort
	KindInteger
	KindLong
	KindFloat
	KindDouble
	KindBigInteger
	KindBigDecimal
	KindTimestamp
	KindDocument
	KindOperation
	KindUnit
)

var kindNames = map[string]Kind{
	"structure": KindStructure, "union": KindUnion, "list": KindList, "set": KindList,
	"map": KindMap, "string": KindString, "enum": KindEnum, "blob": KindBlob,
	"boolean": KindBoolean, "byte": KindByte, "short": KindShort, "integer": KindInteger,
	"intEnum": KindInteger, "long": KindLong, "float": KindFloat, "double": KindDouble,
	"bigInteger": KindBigInteger, "bigDecimal": KindBigDecimal, "timestamp": KindTimestamp,
	"document": KindDocument, "operation": KindOperation,
}

// preludeKinds resolves `~Name` targets — Smithy's prelude shapes.
var preludeKinds = map[string]Kind{
	"String": KindString, "Blob": KindBlob, "Boolean": KindBoolean, "PrimitiveBoolean": KindBoolean,
	"Byte": KindByte, "PrimitiveByte": KindByte, "Short": KindShort, "PrimitiveShort": KindShort,
	"Integer": KindInteger, "PrimitiveInteger": KindInteger, "Long": KindLong, "PrimitiveLong": KindLong,
	"Float": KindFloat, "PrimitiveFloat": KindFloat, "Double": KindDouble, "PrimitiveDouble": KindDouble,
	"BigInteger": KindBigInteger, "BigDecimal": KindBigDecimal, "Timestamp": KindTimestamp,
	"Document": KindDocument, "Unit": KindUnit,
}

// IsNumber reports whether the kind is serialised as a number.
func (k Kind) IsNumber() bool {
	//exhaustive:ignore
	switch k {
	case KindByte, KindShort, KindInteger, KindLong, KindFloat, KindDouble, KindBigInteger, KindBigDecimal:
		return true
	}
	return false
}

// Shape is one decoded shape. Target pointers are resolved within the
// service's table, so a translator walks the graph without lookups.
type Shape struct {
	Name string
	Kind Kind

	// Members of a structure or union, sorted by name.
	Members []*Member

	// Member is a list's element; MemberXMLName its @xmlName.
	Member        *Shape
	MemberXMLName string
	// Key and Value are a map's; KeyXMLName and ValueXMLName their @xmlName.
	Key, Value               *Shape
	KeyXMLName, ValueXMLName string

	XMLName         string
	XMLNamespace    string
	TimestampFormat string
	Streaming       bool

	// Error is "client" or "server" on an error structure; HTTPError its
	// @httpError status and QueryErrorCode its @awsQueryError code.
	Error          string
	HTTPError      int
	QueryErrorCode string

	// Operation fields.
	Input, Output *Shape
	Errors        []*Shape
	Method, URI   string
	HTTPCode      int
}

// Member is one structure or union member with the traits a wire translator
// reads.
type Member struct {
	Name   string
	Target *Shape

	JSONName        string
	XMLName         string
	XMLNamespace    string
	XMLFlattened    bool
	XMLAttribute    bool
	EC2QueryName    string
	TimestampFormat string

	Label        bool
	Query        string
	QueryParams  bool
	Header       string
	PrefixHeader *string
	Payload      bool
	ResponseCode bool
}

// MemberNamed returns a structure's member by exact name.
func (s *Shape) MemberNamed(name string) *Member {
	i := sort.Search(len(s.Members), func(i int) bool { return s.Members[i].Name >= name })
	if i < len(s.Members) && s.Members[i].Name == name {
		return s.Members[i]
	}
	return nil
}

// Service is one service's decoded table.
type Service struct {
	// Key is the canonical model service key ("s3", "api-gateway").
	Key string
	// Protocols lists every protocol trait the service carries.
	Protocols       []awsapi.Protocol
	Version         string
	XMLNamespace    string
	QueryCompatible bool

	shapes map[string]*Shape
	errors map[string]*Shape
}

// Operation returns the named operation shape.
func (s *Service) Operation(name string) (*Shape, bool) {
	shape, ok := s.shapes[name]
	if !ok || shape.Kind != KindOperation {
		return nil, false
	}
	return shape, true
}

// Supports reports whether the service carries the protocol trait.
func (s *Service) Supports(p awsapi.Protocol) bool {
	for _, have := range s.Protocols {
		if have == p {
			return true
		}
	}
	return false
}

// table is one generated service table; tables (index.gen.go) is sorted by
// service.
type table struct {
	service string
	encoded string
}

type cached struct {
	once    sync.Once
	service *Service
	err     error
}

var decoded sync.Map // service key -> *cached

// Lookup returns a service's decoded table, parsing it on first use. ok is
// false when no table was generated for the service.
func Lookup(service string) (*Service, bool, error) {
	i := sort.Search(len(tables), func(i int) bool { return tables[i].service >= service })
	if i >= len(tables) || tables[i].service != service {
		return nil, false, nil
	}
	entry, _ := decoded.LoadOrStore(service, &cached{})
	c := entry.(*cached)
	c.once.Do(func() { c.service, c.err = decode(service, tables[i].encoded) })
	return c.service, true, c.err
}

// Services lists every service key a table was generated for.
func Services() []string {
	out := make([]string, len(tables))
	for i, t := range tables {
		out[i] = t.service
	}
	return out
}

var protocolNames = map[string]awsapi.Protocol{
	"AWSJSON10": awsapi.ProtocolAWSJSON10, "AWSJSON11": awsapi.ProtocolAWSJSON11,
	"AWSQuery": awsapi.ProtocolAWSQuery, "EC2Query": awsapi.ProtocolEC2Query,
	"RESTJSON": awsapi.ProtocolRESTJSON, "RESTXML": awsapi.ProtocolRESTXML,
	"RPCV2CBOR": awsapi.ProtocolRPCV2CBOR, "RPCV2JSON": awsapi.ProtocolRPCV2JSON,
}

// decode parses one table (the format is documented on renderSDKShapes in
// cmd/awsmodelgen/sdkshapes.go) in two passes: declare every shape, then
// resolve references, so forward references need no ordering.
func decode(key, encoded string) (*Service, error) {
	lines := strings.Split(strings.TrimRight(encoded, "\n"), "\n")
	if len(lines) == 0 || !strings.HasPrefix(lines[0], "service ") {
		return nil, fmt.Errorf("awsshapes: %s table has no service header", key)
	}
	svc := &Service{Key: key, shapes: make(map[string]*Shape)}
	header := strings.Fields(lines[0])
	if len(header) > 1 {
		for _, name := range strings.Split(header[1], ",") {
			if p, ok := protocolNames[name]; ok {
				svc.Protocols = append(svc.Protocols, p)
			}
		}
	}
	for _, field := range header[2:] {
		k, v, _ := strings.Cut(field, "=")
		switch k {
		case "version":
			svc.Version = v
		case "ns":
			svc.XMLNamespace = v
		case "querycompat":
			svc.QueryCompatible = true
		}
	}

	type pending struct {
		shape  *Shape
		fields []string
		member []*[]string
	}
	var order []*pending
	var current *pending
	for _, line := range lines[1:] {
		fields := strings.Split(line, " ")
		if strings.HasPrefix(line, ".") {
			if current == nil {
				return nil, fmt.Errorf("awsshapes: %s member line before any shape: %q", key, line)
			}
			f := fields
			current.member = append(current.member, &f)
			continue
		}
		if len(fields) < 2 {
			return nil, fmt.Errorf("awsshapes: %s malformed line %q", key, line)
		}
		kind, ok := kindNames[fields[1]]
		if !ok {
			return nil, fmt.Errorf("awsshapes: %s shape %s has unknown type %q", key, fields[0], fields[1])
		}
		shape := &Shape{Name: fields[0], Kind: kind}
		svc.shapes[shape.Name] = shape
		current = &pending{shape: shape, fields: fields[2:]}
		order = append(order, current)
	}

	prelude := make(map[string]*Shape)
	resolve := func(target string) (*Shape, error) {
		if name, ok := strings.CutPrefix(target, "~"); ok {
			if shape, ok := prelude[name]; ok {
				return shape, nil
			}
			kind, ok := preludeKinds[name]
			if !ok {
				return nil, fmt.Errorf("awsshapes: %s references unknown prelude shape %s", key, name)
			}
			shape := &Shape{Name: name, Kind: kind}
			prelude[name] = shape
			return shape, nil
		}
		shape, ok := svc.shapes[target]
		if !ok {
			return nil, fmt.Errorf("awsshapes: %s references undeclared shape %s", key, target)
		}
		return shape, nil
	}

	for _, p := range order {
		shape := p.shape
		for _, field := range p.fields {
			k, v, _ := strings.Cut(field, "=")
			var err error
			switch k {
			case "in":
				shape.Input, err = resolve(v)
			case "out":
				shape.Output, err = resolve(v)
			case "err":
				for _, name := range strings.Split(v, ",") {
					var e *Shape
					if e, err = resolve(name); err != nil {
						break
					}
					shape.Errors = append(shape.Errors, e)
				}
			case "m":
				shape.Member, err = resolve(v)
			case "k":
				shape.Key, err = resolve(v)
			case "v":
				shape.Value, err = resolve(v)
			case "method":
				shape.Method = v
			case "uri":
				shape.URI = v
			case "code":
				n, _ := strconv.Atoi(v)
				if shape.Kind == KindOperation {
					shape.HTTPCode = n
				} else {
					shape.HTTPError = n
				}
			case "mxml":
				shape.MemberXMLName = v
			case "kxml":
				shape.KeyXMLName = v
			case "vxml":
				shape.ValueXMLName = v
			case "xml":
				shape.XMLName = v
			case "ns":
				shape.XMLNamespace = v
			case "ts":
				shape.TimestampFormat = v
			case "stream":
				shape.Streaming = true
			case "error":
				shape.Error = v
			case "qerr":
				shape.QueryErrorCode = v
			}
			if err != nil {
				return nil, err
			}
		}
		for _, mf := range p.member {
			fields := *mf
			if len(fields) < 2 {
				return nil, fmt.Errorf("awsshapes: %s malformed member line in %s", key, shape.Name)
			}
			target, err := resolve(fields[1])
			if err != nil {
				return nil, err
			}
			m := &Member{Name: fields[0][1:], Target: target}
			for _, field := range fields[2:] {
				k, v, _ := strings.Cut(field, "=")
				switch k {
				case "json":
					m.JSONName = v
				case "xml":
					m.XMLName = v
				case "ns":
					m.XMLNamespace = v
				case "flat":
					m.XMLFlattened = true
				case "attr":
					m.XMLAttribute = true
				case "ec2":
					m.EC2QueryName = v
				case "ts":
					m.TimestampFormat = v
				case "label":
					m.Label = true
				case "query":
					m.Query = v
				case "qparams":
					m.QueryParams = true
				case "header":
					m.Header = v
				case "prefix":
					prefix := v
					m.PrefixHeader = &prefix
				case "payload":
					m.Payload = true
				case "status":
					m.ResponseCode = true
				}
			}
			shape.Members = append(shape.Members, m)
		}
		// The generator emits members sorted, but MemberNamed must not
		// depend on that silently.
		sort.Slice(shape.Members, func(i, j int) bool { return shape.Members[i].Name < shape.Members[j].Name })
	}
	svc.errors = make(map[string]*Shape)
	for _, p := range order {
		if p.shape.Error == "" {
			continue
		}
		svc.errors[p.shape.Name] = p.shape
		if p.shape.QueryErrorCode != "" {
			svc.errors[p.shape.QueryErrorCode] = p.shape
		}
	}
	return svc, nil
}

// ErrorShape resolves a wire error code to the service's modeled error
// structure: by shape name, which is what JSON, REST and RPC v2 protocols
// send, or by @awsQueryError code, which is what a Query service sends when
// the two differ (SQS's AWS.SimpleQueueService.NonExistentQueue).
func (s *Service) ErrorShape(code string) (*Shape, bool) {
	shape, ok := s.errors[code]
	return shape, ok
}

// HasEventStream reports whether an operation streams events in either
// direction — an operation no request/response client can call.
func (s *Shape) HasEventStream() bool {
	for _, io := range []*Shape{s.Input, s.Output} {
		if io == nil {
			continue
		}
		for _, m := range io.Members {
			if m.Target.Kind == KindUnion && m.Target.Streaming {
				return true
			}
		}
	}
	return false
}
